window.AUTH=window.AUTH||{};window.AUTH["09-804"]={"d":"09-804","id":"2010/09-804","n":"CIGNA v. Amara","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondents","date":"","url":"https://www.justice.gov/osg/media/197931/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/cigna-corp-v-amara-amicus-merits","n":66}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep563/usrep563421/usrep563421.pdf","tr":true,"items":[{"t":"case","label":"Aetna Health Inc. v. Davila","cite":"542 U.S. 200","y":2004,"id":"2003/02-1845","sc":1,"sum":"The Court held that Congress intended ERISA to provide a uniform system for regulating retirement schemes and benefits. If a state law conflicts with ERISA, therefore, ERISA must be used in its place.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Affiliated Ute Citizens v. United States","cite":"406 U.S. 128","y":1972,"id":"1971/70-78","sc":1,"sum":"The Ute Partition Act was designed to provide for the partition and distribution of the tribe's assets between the mixed-blood and fullblood members; for termination of federal supervision over the trust and restricted property of mixed-bloods; and for a development program for the full-bloods with a view toward terminating federal supervision of them. In addition to cash and land, the tribe owned oil, gas, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Basic Inc. v. Levinson","cite":"485 U.S. 224","y":1988,"id":"1987/86-279","sc":1,"sum":"The Supreme Court held that there was no reason to artificially exclude merger conversations from the definition of materiality simply because they do not include specific prices.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Basile v. H&R Block","cite":"777 A.2d 95","y":2001,"court":"Pa. Super. Ct.","url":"https://www.courtlistener.com/c/A.2d/777/95/","by":{"0":"25"}},{"t":"case","label":"Branch v. G. Bernd Co.","cite":"955 F.2d 1574","y":1992,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/955/1574/","by":{"0":"26"}},{"t":"case","label":"Branch v. White","cite":"239 A.2d 665","y":1968,"court":"N.J. Super. Ct. App. Div.","url":"https://www.courtlistener.com/c/A.2d/239/665/","by":{"0":"18"}},{"t":"case","label":"Bridge v. Phoenix Bond & Indem. Co.","cite":"553 U.S. 639","y":2010,"id":"2007/07-210","sc":1,"ar":1,"sum":"The Court held in favor of Phoenix, stating that a plaintiff bringing a RICO claim based on mail fraud does not need to show that it actually relied on the defendant's misrepresentations. Plaintiffs do not lack standing merely because the false statements were made to a third party.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Burke v. Kodak Ret. Income Plan","cite":"336 F.3d 103","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/336/103/","by":{"0":"6, 11, 20, 21"}},{"t":"case","label":"Burstein v. Retirement Account Plan for Employees of Allegheny Health Educ. & Research Found.","cite":"334 F.3d 365","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/334/365/","ar":1,"by":{"0":"13, 16, 23, 24, 27"}},{"t":"case","label":"Callery v. United States Life Ins. Co.","cite":"392 F.3d 401","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/392/401/","by":{"0":"30"}},{"t":"case","label":"Central Laborers’ Pension Fund v. Heinz","cite":"541 U.S. 739","y":2004,"id":"2003/02-891","sc":1,"sum":"The Court unanimously held that the amendment to the plan had narrowed Heinz's rights to the benefits promised him at the time he retired, and that such a narrowing violated ERISA. Justice David H. Souter, in the Opinion of the Court, wrote, \"'[A] participant's benefits cannot be understood without reference to the conditions imposed on receiving those benefits.' .","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Communications Workers v. AT&T Co.","cite":"40 F.3d 426","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/40/426/","by":{"0":"29"}},{"t":"case","label":"Conkright v. Frommert","cite":"130 S. Ct. 1640","y":2010,"id":"2009/08-810","sc":1,"op":1,"ar":1,"sum":"The Court held that the Second Circuit Court of Appeals erred when they did not hold a claim of unfair pension distribution by employees of the Xerox Corporation to a deferential standard of review.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Curtiss-Wright Corp. v. Schoonejongen","cite":"514 U.S. 734","y":1995,"id":"1994/93-1935","sc":1,"op":1,"ar":8,"sum":"Petitioner Curtiss-Wright Corp. amended its employee benefit plan to provide that the postretirement health care coverage it had maintained for many years would cease for retirees upon the termination of business operations in the facility from which they retired. In ruling for respondent retirees in their ensuing suit, the District Court found, among other things, that the new provision constituted an \"amendment\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 13, 19, 22, 24"}},{"t":"case","label":"Edmunds v. Valley Circle Estates","cite":"20 Cal. Rptr. 2d 701","y":1993,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr.%202d/20/701/","by":{"0":"25"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Bruch","cite":"489 U.S. 101","y":1989,"id":"1988/87-1054","sc":1,"ar":1,"sum":"Petitioner Firestone Tire & Rubber Co. (Firestone) maintained, and was the plan administrator and fiduciary of, a termination pay plan and two other unfunded employee benefit plans governed by the Employee Retirement Income Security Act of 1974 (ERISA), 29 U. S. C. § 1001 et seq. After Firestone sold its Plastics Division to Occidental Petroleum Co. (Occidental), respondents, Plastics Division employees who were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 15, 26"}},{"t":"case","label":"Gould v. Continental Coffee Co.","cite":"304 F. Supp. 1","y":1969,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./304/1/","by":{"0":"26"}},{"t":"case","label":"Govoni v. Bricklayers, Masons & Plasterers Int’l Union, Local No. 5 Pension Fund","cite":"732 F.2d 250","y":1984,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/732/250/","ar":1,"by":{"0":"32"}},{"t":"case","label":"Gridley v. Cleveland Pneumatic Co.","cite":"924 F.2d 1310","y":1991,"url":"https://www.courtlistener.com/c/F.2d/924/1310/","by":{"0":"23"}},{"t":"case","label":"Heffner v. Blue Cross & Blue Shield of Ala. Inc.","cite":"443 F.3d 1330","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/443/1330/","by":{"0":"26"}},{"t":"case","label":"Heidgard v. Olin Corp.","cite":"906 F.2d 903","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/906/903/","by":{"0":"15, 27"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. United States Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Jobe v. Medical Life Ins. Co.","cite":"598 F.3d 478","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/598/478/","by":{"0":"20"}},{"t":"case","label":"Kennedy v. Plan Adm’r for DuPont Sav. & Inv. Plan","cite":"129 S. Ct. 865","y":2009,"id":"2008/07-636","sc":1,"sum":"The Court held that the Employee Retirement Income Security Act's anti-alienation provision nonetheless recognizes a wavier which holds that a spouse's right to the other spouse's pension benefits is void upon divorce.","sumSrc":"Oyez","by":{"0":"12, 14, 21, 28"}},{"t":"case","label":"Kosty v. Lewis","cite":"319 F.2d 744","y":1963,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/319/744/","by":{"0":"27"}},{"t":"case","label":"Martin v. Feilen","cite":"965 F.2d 660","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/965/660/","by":{"0":"18"}},{"t":"case","label":"Massachusetts Mut. Life Ins. Co. v. Russell","cite":"473 U.S. 134","y":1985,"id":"1984/84-9","sc":1,"sum":"Section 409(a) does not provide a cause of action for extracontractual damages to a beneficiary caused by improper or untimely processing of benefit claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Mathews v. Chevron Corp.","cite":"362 F.3d 1172","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/362/1172/","by":{"0":"30"}},{"t":"case","label":"McDonald v. Provident Indem. Life Ins. Corp.","cite":"60 F.3d 234","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/60/234/","by":{"0":"18"}},{"t":"case","label":"Miller v. Dictaphone Corp.","cite":"334 F. Supp. 840","y":1971,"court":"D. Ore.","url":"https://www.courtlistener.com/c/F.%20Supp./334/840/","by":{"0":"26"}},{"t":"case","label":"Nechis v. Oxford Health Plans, Inc.","cite":"421 F.3d 96","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/421/96/","by":{"0":"30"}},{"t":"case","label":"Nedd v. United Mine Workers","cite":"556 F.2d 190","y":1977,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/556/190/","by":{"0":"18"}},{"t":"case","label":"Pegram v. Herdrich","cite":"530 U.S. 211","y":2000,"id":"1999/98-1949","sc":1,"sum":"The Court held that mixed treatment and eligibility decisions to delay medical treatment by sending a patient to a HMO owned facility, with adverse consequences, made by a health maintenance organization through its physician, are not fiduciary decisions under ERISA.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Pierce v. Security Trust Life Ins. Co.","cite":"979 F.2d 23","y":1992,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/979/23/","by":{"0":"32"}},{"t":"case","label":"Pisciotta v. Teledyne Indus., Inc.","cite":"91 F.3d 1326","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/91/1326/","by":{"0":"27"}},{"t":"case","label":"Rhoton v. Central States, Se. & Sw. Areas Pension Fund","cite":"717 F.2d 988","y":1983,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/717/988/","by":{"0":"14"}},{"t":"case","label":"Schad v. Stamford Health Sys., Inc.","cite":"358 Fed. Appx. 242","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./358/242/","by":{"0":"11"}},{"t":"case","label":"Silverman v. Mutual Benefit Life Ins. Co.","cite":"138 F.3d 98","y":1998,"url":"https://www.courtlistener.com/c/F.3d/138/98/","by":{"0":"18"}},{"t":"case","label":"Smith v. Sydnor","cite":"184 F.3d 356","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/184/356/","by":{"0":"29"}},{"t":"case","label":"Sullivan v. Louisiana","cite":"508 U.S. 275","y":1993,"id":"1992/92-5129","sc":1,"op":2,"sum":"A constitutionally deficient reasonable-doubt instruction cannot be harmless error.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Unum Life Ins. Co. of Am. v. Ward","cite":"526 U.S. 358","y":1999,"id":"1998/97-1868","sc":1,"op":1,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that California's agency rule is preempted by the Employee Retirement Income Security Act of 1974. Justice Ginsburg wrote for the Court that California's common-law agency rule \"would have a marked effect on plan administration,\" adding that it would force employers to take on a role for which they had not volunteered.","sumSrc":"Oyez","by":{"0":"28, 29"}},{"t":"case","label":"Varity Corp. v. Howe","cite":"516 U.S. 489","y":1996,"id":"1995/94-1471","sc":1,"op":3,"ar":1,"sum":"The Court held that, under the specific factual circumstances, Varity and Massey-Ferguson acted in their capacity as an ERISA fiduciary when they significantly and deliberately misled the plan's beneficiaries, thereby violating their fiduciary obligations imposed by ERISA.","sumSrc":"Oyez","by":{"0":"16, 28, 30"}},{"t":"case","label":"Voigt v. South Side Laundry & Dry Cleaners, Inc.","cite":"128 N.W.2d 411","y":1964,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/128/411/","by":{"0":"26"}},{"t":"case","label":"Washington v. Murphy Oil USA, Inc.","cite":"497 F.3d 453","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/497/453/","by":{"0":"16"}},{"t":"case","label":"Watts v. Cumberland County Hosp. Sys. Inc.","cite":"343 S.E.2d 879","y":1986,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E.2d/343/879/","by":{"0":"25"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","subs":["(b)"],"stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"1, 12"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(1)","(2)(A)","(3)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1002. Definitions","tname":"Labor","by":{"0":"22, 2, 1"}},{"t":"usc","label":"29 U.S.C. § 1022","url":"https://www.law.cornell.edu/uscode/text/29/1022","subs":["(a)","(b)"],"stext":{"head":"§1022. Summary plan description","paras":[[0,"(a) A summary plan description of any employee benefit plan shall be furnished to participants and beneficiaries as provided in section 1024(b) of this title. The summary plan description shall include the information described in subsection (b), shall be written in a manner calculated to be understood by the average plan participant, and shall be sufficiently accurate and comprehensive to reasonably apprise such participants and beneficiaries of their rights and obligations under the plan. A summary of any material modification in the terms of the plan and any change in the information required under subsection (b) shall be written in a manner calculated to be understood by the average plan participant and shall be furnished in accordance with section 1024(b)(1) of this title."],[0,"(b) The summary plan description shall contain the following information: The name and type of administration of the plan; in the case of a group health plan (as defined in section 1191b(a)(1) of this title), whether a health insurance issuer (as defined in section 1191b(b)(2) of this title) is responsible for the financing or administration (including payment of claims) of the plan and (if so) the name and address of such issuer; the name and address of the person designated as agent for the service of legal process, if such person is not the administrator; the name and address of the administrator; names, titles, and addresses of any trustee or trustees (if they are persons different from the administrator); a description of the relevant provisions of any applicable collective bargaining agreement; the plan's requirements respecting eligibility for participation and benefits; a description of the provisions providing for nonforfeitable pension benefits; circumstances which may result in disqualification, ineligibility, or denial or loss of benefits; the source of financing of the plan and the identity of any organization through which benefits are provided; the date of the end of the plan year and whether the records of the plan are kept on a calendar, policy, or fiscal year basis; the procedures to be followed in presenting claims for benefits under the plan including the office at the Department of Labor through which participants and beneficiaries may seek assistance or information regarding their rights under this chapter and the Health Insurance Portability and Accountability Act of 1996 with respect to health benefits that are offered through a group health plan (as defined in section 1191b(a)(1) of this title), the remedies available under the plan for the redress of claims which are denied in whole or in part (including procedures required under section 1133 of this title), and if the employer so elects for purposes of complying with section 1181(f)(3)(B)(i) of this title, the model notice applicable to the State in which the participants and beneficiaries reside."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1022?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1022. Summary plan description","tname":"Labor","by":{"0":"8, 15, 20, 23, 2, 14, 17, 19, 22, 14"}},{"t":"usc","label":"29 U.S.C. § 1024","url":"https://www.law.cornell.edu/uscode/text/29/1024","subs":["(b)(1)","(b)(2)","(b)(4)"],"stext":{"head":"§1024. Filing with Secretary and furnishing information to participants and certain employers","paras":[[0,"(a) Filing of annual report with Secretary"],[0,"(1) The administrator of any employee benefit plan subject to this part shall file with the Secretary the annual report for a plan year within 210 days after the close of such year (or within such time as may be required by regulations promulgated by the Secretary in order to reduce duplicative filing). The Secretary shall make copies of such annual reports available for inspection in the public document room of the Department of Labor."],[0,"(2)(A) With respect to annual reports required to be filed with the Secretary under this part, the Secretary may by regulation prescribe simplified annual reports for any pension plan that—"],[1,"(i) covers fewer than 100 participants; or"],[1,"(ii) is a plan described in section 1060(a) of this title that covers fewer than 1,000 participants, but only if no single employer in the plan has 100 or more participants covered by the plan."],[0,"(B) Nothing contained in this paragraph shall preclude the Secretary from requiring any information or data from any such plan to which this part applies where he finds such data or information is necessary to carry out the purposes of this subchapter nor shall the Secretary be precluded from revoking provisions for simplified reports for any such plan if he finds it necessary to do so in order to carry out the objectives of this subchapter."],[0,"(3) The Secretary may by regulation exempt any welfare benefit plan from all or part of the reporting and disclosure requirements of this subchapter, or may provide for simplified reporting and disclosure if he finds that such requirements are inappropriate as applied to welfare benefit plans."],[0,"(4) The Secretary may reject any filing under this section—"],[1,"(A) if he determines that such filing is incomplete for purposes of this part; or"],[1,"(B) if he determines that there is any material qualification by an accountant or actuary contained in an opinion submitted pursuant to section 1023(a)(3)(A) or section 1023(a)(4)(B) of this title."],[0,"(5) If the Secretary rejects a filing of a report under paragraph (4) and if a revised filing satisfactory to the Secretary is not submitted within 45 days after the Secretary makes his determination under paragraph (4) to reject the filing, and if the Secretary deems it in the best interest of the participants, he may take any one or more of the following actions—"],[1,"(A) retain an independent qualified public accountant (as defined in section 1023(a)(3)(D) of this title) on behalf of the participants to perform an audit,"],[1,"(B) retain an enrolled actuary (as defined in section 1023(a)(4)(C) of this title) on behalf of the plan participants, to prepare an actuarial statement,"],[1,"(C) bring a civil action for such legal or equitable relief as may be appropriate to enforce the provisions of this part, or"],[1,"(D) take any other action authorized by this subchapter."],[0,"The administrator shall permit such accountant or actuary to inspect whatever books and records of the plan are necessary for such audit. The plan shall be liable to the Secretary for the expenses for such audit or report, and the Secretary may bring an action against the plan in any court of competent jurisdiction to recover such expenses."],[0,"(6) The administrator of any employee benefit plan subject to this part shall furnish to the Secretary, upon request, any documents relating to the employee benefit plan, including but not limited to, the latest summary plan description (including any summaries of plan changes not contained in the summary plan description), and the bargaining agreement, trust agreement, contract, or other instrument under which the plan is established or operated."],[0,"(b) Publication of summary plan description and annual report to participants and beneficiaries of plan"],[0,"Publication of the summary plan descriptions and annual reports shall be made to participants and beneficiaries of the particular plan as follows:"],[0,"(1) The administrator shall furnish to each participant, and each beneficiary receiving benefits under the plan, a copy of the summary plan description, and all modifications and changes referred to in section 1022(a) of this title—"],[1,"(A) within 90 days after he becomes a participant, or (in the case of a beneficiary) within 90 days after he first receives benefits, or"],[1,"(B) if later, within 120 days after the plan becomes subject to this part."],[0,"The administrator shall furnish to each participant, and each beneficiary receiving benefits under the plan, every fifth year after the plan becomes subject to this part an updated summary plan description described in section 1022 of this title which integrates all plan amendments made within such five-year period, except that in a case where no amendments have been made to a plan during such five-year period this sentence shall not apply. Notwithstanding the foregoing, the administrator shall furnish to each participant, and to each beneficiary receiving benefits under the plan, the summary plan description described in section 1022 of this title every tenth year after the plan becomes subject to this part. If there is a modification or change described in section 1022(a) of this title (other than a material reduction in covered services or benefits provided in the case of a group health plan (as defined in section 1191b(a)(1) of this title)), a summary description of such modification or change shall be furnished not later than 210 days after the end of the plan year in which the change is adopted to each participant, and to each beneficiary who is receiving benefits under the plan. If there is a modification or change described in section 1022(a) of this title that is a material reduction in covered services or benefits provided under a group health plan (as defined in section 1191b(a)(1) of this title), a summary description of such modification or change shall be furnished to participants and beneficiaries not later than 60 days after the date of the adoption of the modification or change. In the alternative, the plan sponsors may provide such description at regular intervals of not more than 90 days. The Secretary shall issue regulations within 180 days after August 21, 1996, providing alternative mechanisms to delivery by mail through which group health plans (as so defined) may notify participants and beneficiaries of material reductions in covered services or benefits."],[0,"(2) The administrator shall make copies of the latest updated summary plan description and the latest annual report and the bargaining agreement, trust agreement, contract, or other instruments under which the plan was established or is operated available for examination by any plan participant or beneficiary in the principal office of the administrator and in such other places as may be necessary to make available all pertinent information to all participants (including such places as the Secretary may prescribe by regulations)."],[0,"(3) Within 210 days after the close of the fiscal year of the plan, the administrator (other than an administrator of a defined benefit plan to which the requirements of section 1021(f) of this title applies) 1 shall furnish to each participant, and to each beneficiary receiving benefits under the plan, a copy of the statements and schedules, for such fiscal year, described in subparagraphs (A) and (B) of section 1023(b)(3) of this title and such other material (including the percentage determined under section 1023(d)(11) of this title) as is necessary to fairly summarize the latest annual report."],[0,"(4) The administrator shall, upon written request of any participant or beneficiary, furnish a copy of the latest updated summary,2 plan description, and the latest annual report, any terminal report, the bargaining agreement, trust agreement, contract, or other instruments under which the plan is established or operated. The administrator may make a reasonable charge to cover the cost of furnishing such complete copies. The Secretary may by regulation prescribe the maximum amount which will constitute a reasonable charge under the preceding sentence."],[0,"(5) Identification and basic plan information and actuarial information included in the annual report for any plan year shall be filed with the Secretary in an electronic format which accommodates display on the Internet, in accordance with regulations which shall be prescribed by the Secretary. The Secretary shall provide for display of such information included in the annual report, within 90 days after the date of the filing of the annual report, on an Internet website maintained by the Secretary and other appropriate media. Such information shall also be displayed on any Intranet website maintained by the plan sponsor (or by the plan administrator on behalf of the plan sponsor) for the purpose of communicating with employees and not the public, in accordance with regulations which shall be prescribed by the Secretary."],[0,"(c) Statement of rights"],[0,"The Secretary may by regulation require that the administrator of any employee benefit plan furnish to each participant and to each beneficiary receiving benefits under the plan a statement of the rights of participants and beneficiaries under this subchapter."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1024?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§1024. Filing with Secretary and furnishing information to participants and certain employers","tname":"Labor","by":{"0":"2, 13, 23, 12, 13, 23, 12, 13, 22, 23"}},{"t":"usc","label":"29 U.S.C. § 1029","url":"https://www.law.cornell.edu/uscode/text/29/1029","subs":["(c)"],"by":{"0":"22"}},{"t":"usc","label":"29 U.S.C. § 1054","url":"https://www.law.cornell.edu/uscode/text/29/1054","subs":["(b)(5)(B)(iii)","(g)","(h)"],"stext":{"head":"§1054. Benefit accrual requirements","paras":[[0,"(a) Satisfaction of requirements by pension plans"],[0,"Each pension plan shall satisfy the requirements of subsection (b)(3), and—"],[1,"(1) in the case of a defined benefit plan, shall satisfy the requirements of subsection (b)(1); and"],[1,"(2) in the case of a defined contribution plan, shall satisfy the requirements of subsection (b)(2)."],[0,"(b) Enumeration of plan requirements"],[0,"(1)(A) A defined benefit plan satisfies the requirements of this paragraph if the accrued benefit to which each participant is entitled upon his separation from the service is not less than—"],[1,"(i) 3 percent of the normal retirement benefit to which he would be entitled at the normal retirement age if he commenced participation at the earliest possible entry age under the plan and served continuously until the earlier of age 65 or the normal retirement age specified under the plan, multiplied by"],[1,"(ii) the number of years (not in excess of 331/3) of his participation in the plan."],[0,"In the case of a plan providing retirement benefits based on compensation during any period, the normal retirement benefit to which a participant would be entitled shall be determined as if he continued to earn annually the average rate of compensation which he earned during consecutive years of service, not in excess of 10, for which his compensation was the highest. For purposes of this subparagraph, social security benefits and all other relevant factors used to compute benefits shall be treated as remaining constant as of the current year for all years after such current year."],[0,"(B) A defined benefit plan satisfies the requirements of this paragraph of a particular plan year if under the plan the accrued benefit payable at the normal retirement age is equal to the normal retirement benefit and the annual rate at which any individual who is or could be a participant can accrue the retirement benefits payable at normal retirement age under the plan for any later plan year is not more than 1331/3 percent of the annual rate at which he can accrue benefits for any plan year beginning on or after such particular plan year and before such later plan year. For purposes of this subparagraph—"],[1,"(i) any amendment to the plan which is in effect for the current year shall be treated as in effect for all other plan years;"],[1,"(ii) any change in an accrual rate which does not apply to any individual who is or could be a participant in the current year shall be disregarded;"],[1,"(iii) the fact that benefits under the plan may be payable to certain employees before normal retirement age shall be disregarded; and"],[1,"(iv) social security benefits and all other relevant factors used to compute benefits shall be treated as remaining constant as of the current year for all years after the current year."],[0,"(C) A defined benefit plan satisfies the requirements of this paragraph if the accrued benefit to which any participant is entitled upon his separation from the service is not less than a fraction of the annual benefit commencing at normal retirement age to which he would be entitled under the plan as in effect on the date of his separation if he continued to earn annually until normal retirement age the same rate of compensation upon which his normal retirement benefit would be computed under the plan, determined as if he had attained normal retirement age on the date any such determination is made (but taking into account no more than the 10 years of service immediately preceding his separation from service). Such fraction shall be a fraction, not exceeding 1, the numerator of which is the total number of his years of participation in the plan (as of the date of his separation from the service) and the denominator of which is the total number of years he would have participated in the plan if he separated from the service at the normal retirement age. For purposes of this subparagraph, social security benefits and all other relevant factors used to compute benefits shall be treated as remaining constant as of the current year for all years after such current year."],[0,"(D) Subparagraphs (A), (B), and (C) shall not apply with respect to years of participation before the first plan year to which this section applies but a defined benefit plan satisfies the requirements of this subparagraph with respect to such years of participation only if the accrued benefit of any participant with respect to such years of participation is not less than the greater of—"],[1,"(i) his accrued benefit determined under the plan, as in effect from time to time prior to September 2, 1974, or"],[1,"(ii) an accrued benefit which is not less than one-half of the accrued benefit to which such participant would have been entitled if subparagraph (A), (B), or (C) applied with respect to such years of participation."],[0,"(E) Notwithstanding subparagraphs (A), (B), and (C) of this paragraph, a plan shall not be treated as not satisfying the requirements of this paragraph solely because the accrual of benefits under the plan does not become effective until the employee has two continuous years of service. For purposes of this subparagraph, the term \"year of service\" has the meaning provided by section 1052(a)(3)(A) of this title."],[0,"(F) Notwithstanding subparagraphs (A), (B), and (C), a defined benefit plan satisfies the requirements of this paragraph if such plan"],[1,"(i) is funded exclusively by the purchase of insurance contracts, and"],[1,"(ii) satisfies the requirements of paragraphs (2) and (3) of section 1081(b) of this title (relating to certain insurance contract plans),"],[0,"but only if an employee's accrued benefit as of any applicable date is not less than the cash surrender value his insurance contracts would have on such applicable date if the requirements of paragraphs (4), (5), and (6) of section 1081(b) of this title were satisfied."],[0,"(G) Notwithstanding the preceding subparagraphs, a defined benefit plan shall be treated as not satisfying the requirements of this paragraph if the participant's accrued benefit is reduced on account of any increase in his age or service. The preceding sentence shall not apply to benefits under the plan commencing before benefits payable under title II of the Social Security Act [42 U.S.C. 401 et seq.] which benefits under the plan—"],[1,"(i) do not exceed social security benefits, and"],[1,"(ii) terminate when such social security benefits commence."],[0,"(H)(i) Notwithstanding the preceding subparagraphs, a defined benefit plan shall be treated as not satisfying the requirements of this paragraph if, under the plan, an employee's benefit accrual is ceased, or the rate of an employee's benefit accrual is reduced, because of the attainment of any age."],[0,"(ii) A plan shall not be treated as failing to meet the requirements of this subparagraph solely because the plan imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(iii) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(I) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subparagraph for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(II) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title, then any requirement of this subparagraph for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The preceding provisions of this clause shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations may provide for the application of the preceding provisions of this clause, in the case of any such employee, with respect to any period of time within a plan year."],[0,"(iv) Clause (i) shall not apply with respect to any employee who is a highly compensated employee (within the meaning of section 414(q) of title 26) to the extent provided in regulations prescribed by the Secretary of the Treasury for purposes of precluding discrimination in favor of highly compensated employees within the meaning of subchapter D of chapter 1 of title 26."],[0,"(v) A plan shall not be treated as failing to meet the requirements of clause (i) solely because the subsidized portion of any early retirement benefit is disregarded in determining benefit accruals."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1054?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1054. Benefit accrual requirements","tname":"Labor","by":{"0":"3, 33, 3, 4, 3"}},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(a)(1)","(b)(3)"],"stext":{"head":"§1102. Establishment of plan","paras":[[0,"(a) Named fiduciaries"],[0,"(1) Every employee benefit plan shall be established and maintained pursuant to a written instrument. Such instrument shall provide for one or more named fiduciaries who jointly or severally shall have authority to control and manage the operation and administration of the plan."],[0,"(2) For purposes of this subchapter, the term \"named fiduciary\" means a fiduciary who is named in the plan instrument, or who, pursuant to a procedure specified in the plan, is identified as a fiduciary (A) by a person who is an employer or employee organization with respect to the plan or (B) by such an employer and such an employee organization acting jointly."],[0,"(b) Requisite features of plan"],[0,"Every employee benefit plan shall—"],[1,"(1) provide a procedure for establishing and carrying out a funding policy and method consistent with the objectives of the plan and the requirements of this subchapter,"],[1,"(2) describe any procedure under the plan for the allocation of responsibilities for the operation and administration of the plan (including any procedure described in section 1105(c)(1) of this title),"],[1,"(3) provide a procedure for amending such plan, and for identifying the persons who have authority to amend the plan, and"],[1,"(4) specify the basis on which payments are made to and from the plan."],[0,"(c) Optional features of plan"],[0,"Any employee benefit plan may provide—"],[1,"(1) that any person or group of persons may serve in more than one fiduciary capacity with respect to the plan (including service both as trustee and administrator);"],[1,"(2) that a named fiduciary, or a fiduciary designated by a named fiduciary pursuant to a plan procedure described in section 1105(c)(1) of this title, may employ one or more persons to render advice with regard to any responsibility such fiduciary has under the plan; or"],[1,"(3) that a person who is a named fiduciary with respect to control or management of the assets of the plan may appoint an investment manager or managers to manage (including the power to acquire and dispose of) any assets of a plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1102?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1102. Establishment of plan","tname":"Labor","by":{"0":"13, 22, 24"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)(D)"],"by":{"0":"passim"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(1)(B)","(a)(3)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"10, 27, 29, 30, 10, 27, 29, 30"}}]};